<?php defined('BASEPATH') OR exit('No direct script access allowed'); $ci =& get_instance(); $open=array_filter($jobs,function($j){return !in_array($j->status,['completed','cancelled'],true);}); ?>
<div class="bm-ops"><header class="bo-head"><div><span class="bo-eyebrow"><?= $services?'Customer support & after-sales':'Execution & site visits'; ?></span><h1><?= htmlspecialchars($page_title); ?></h1><p><?= $services?'Specific repair, maintenance and calibration work orders. Projects coordinate the wider commercial delivery.':'Assign responsible engineers, schedule installations and review visit progress. Attendance shifts are available under More.'; ?></p></div><?php if($ci->permissions('service_jobs_add')): ?><a class="bo-button primary" href="<?= base_url('operations/service_job_form?job_type='.($services?'maintenance':'installation')); ?>"><i class="fa fa-plus"></i> <?= $services?'New service request':'Schedule installation'; ?></a><?php endif; ?></header>
  <div class="bo-summary"><div class="bo-card"><small>Open work orders</small><strong><?= count($open); ?></strong></div><div class="bo-card"><small>Unassigned</small><strong><?= count(array_filter($open,function($j){return !$j->assigned_user_id;})); ?></strong></div><div class="bo-card"><small>Visits today</small><strong><?= count(array_filter($open,function($j){return $j->scheduled_date===date('Y-m-d');})); ?></strong></div><div class="bo-card"><small>Awaiting parts</small><strong><?= count(array_filter($open,function($j){return $j->status==='awaiting_parts';})); ?></strong></div></div>
  <?php if($services): ?><nav class="bo-tabs" aria-label="Service types"><a href="<?= base_url('building_workspace/services'); ?>" <?= !$selected_type?'aria-current="page"':''; ?>>All service requests</a><?php foreach(['maintenance','repair','calibration'] as $type): ?><a href="<?= base_url('building_workspace/services?type='.$type); ?>" <?= $selected_type===$type?'aria-current="page"':''; ?>><?= ucfirst($type); ?></a><?php endforeach; ?></nav><?php endif; ?>
  <section class="bo-card"><h2><?= $services?'Service work orders':'Installation work orders'; ?></h2><div class="bo-table-wrap"><table class="bo-table"><thead><tr><th>Work order</th><th>Customer / site</th><th>Engineer</th><th>Scheduled</th><th>Status</th><th>Next action</th></tr></thead><tbody><?php foreach($jobs as $job): ?><tr><td><strong><?= htmlspecialchars($job->title ?: $job->job_code); ?></strong><small><?= htmlspecialchars($job->job_code.' · '.ucfirst($job->job_type)); ?></small></td><td><?= htmlspecialchars($job->customer_name ?: 'Customer'); ?><small><?= htmlspecialchars($job->site_name ?: 'Customer primary address'); ?></small></td><td><?= htmlspecialchars($job->engineer ?: 'Unassigned'); ?></td><td><?= htmlspecialchars($job->scheduled_date ?: 'Not scheduled'); ?></td><td><span class="bo-pill"><?= htmlspecialchars(ucwords(str_replace('_',' ',$job->status))); ?></span></td><td><div class="bo-row-actions"><a class="bo-button compact" href="<?= base_url($job->is_project?'building_projects/'.(int)$job->id:'operations/service_job_view/'.(int)$job->id); ?>"><?= $job->is_project?'Open project':'Open work order'; ?></a><?php if($ci->permissions('service_jobs_edit')): ?><a href="<?= base_url('operations/service_job_form/'.(int)$job->id); ?>">Assign / schedule</a><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$jobs): ?><tr><td colspan="6"><div class="bo-empty"><h3><?= $services?'No service requests found':'No installation work orders found'; ?></h3><p><?= $services?'Create a service request for a customer who needs repair or maintenance.':'Schedule an installation for a customer or create a project for a larger scope of work.'; ?></p></div></td></tr><?php endif; ?></tbody></table></div></section>
</div>
